// Jobtiva database schema — the single source of truth (TRD §4, §6).
//
// Two groups:
//  1. Auth tables (user/session/account/verification) — generated by Better
//     Auth's CLI into ./auth-schema.ts, re-exported here so migrations cover
//     them. Do not hand-edit auth-schema.ts; re-run `npm run auth:generate`.
//  2. Application tables — one column per field a Phase-1 screen reads/writes.
//     `lib/types.ts` is the UI-side mirror of these shapes.
//
// Every application table carries `user_id` (text, FK → user.id) from day one
// so a future second user needs no migration; today all rows are the one owner.
// NOTE: Better Auth's default IDs are `text`, so `user_id` is text — not uuid
// as an earlier draft of the schema plan assumed.

import { sql } from "drizzle-orm";
import {
  pgTable,
  pgEnum,
  text,
  boolean,
  integer,
  smallint,
  real,
  uuid,
  date,
  timestamp,
  jsonb,
  uniqueIndex,
  primaryKey,
  check,
  index,
  customType,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";

import { user } from "./auth-schema";
import type { SalaryInsight } from "../lib/types";
import type { InterviewSettingsSnapshot, MetricWeights, PlannedQuestion, PricingByDifficulty, ReportWriting } from "../lib/mock-interviews/model";

// Raw bytes column (node-postgres returns/accepts a Buffer).
const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType() {
    return "bytea";
  },
});

// Auth tables live alongside app tables in every migration.
export * from "./auth-schema";

/* ------------------------------------------------------------------ */
/* Enums (mirror the unions in lib/types.ts)                           */
/* ------------------------------------------------------------------ */

export const leadStatus = pgEnum("lead_status", [
  "new",
  "shortlisted",
  "applied",
  "interview",
  "offer-received",
  "discarded",
  "closed",
]);
// How a lead got in: the Gmail sync ("system") or the Add-lead form ("manual").
export const leadOrigin = pgEnum("lead_origin", ["system", "manual"]);
export const closeOutcome = pgEnum("close_outcome", [
  "offer",
  "rejected",
  "withdrawn",
  "no-response",
  "position-closed",
]);
export const connectionType = pgEnum("connection_type", [
  "recruiter",
  "referral",
  "hiring-manager",
  "other",
]);
export const outreachKind = pgEnum("outreach_kind", [
  "referral-ask",
  "cold-outreach",
  "follow-up",
]);
export const outreachStatus = pgEnum("outreach_status", ["draft", "sent"]);
export const reminderOutcome = pgEnum("reminder_outcome", [
  "pending",
  "reminder-sent",
  "response-received",
  "closed",
  "not-responded",
]);
export const taskKind = pgEnum("task_kind", ["follow-up", "decision", "manual"]);
export const taskStatus = pgEnum("task_status", ["open", "done"]);
export const aiProvider = pgEnum("ai_provider", [
  "openai",
  "anthropic",
  "openrouter",
]);
export const resumeFileType = pgEnum("resume_file_type", ["pdf", "doc", "docx"]);
export const planStatus = pgEnum("plan_status", ["active", "inactive"]);
export const ticketStatus = pgEnum("ticket_status", ["open", "in_progress", "resolved"]);

/* ------------------------------------------------------------------ */
/* Application tables                                                   */
/* ------------------------------------------------------------------ */

/** One row per parsed alert email — the automated-ingestion anchor (maps JobLead). */
export const jobLeads = pgTable(
  "job_leads",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // Dedupe key (FR-1.5), parsed from the canonical URL.
    linkedinJobId: text("linkedin_job_id").notNull(),
    title: text("title").notNull(),
    company: text("company").notNull(),
    location: text("location").notNull(),
    remote: boolean("remote").notNull().default(false),
    tags: text("tags").array().notNull().default(sql`'{}'::text[]`),
    postedRelative: text("posted_relative").notNull(),
    canonicalJobUrl: text("canonical_job_url").notNull(),
    status: leadStatus("status").notNull().default("new"),
    closeOutcome: closeOutcome("close_outcome"), // set only when status = closed
    // Job platform, derived from the URL (lib/lead-source.ts). Text, not an enum,
    // so a new platform is a code change only.
    source: text("source").notNull().default("other"),
    origin: leadOrigin("origin").notNull().default("manual"),
    // Starred by the user (golden card + Top Choice filter).
    topChoice: boolean("top_choice").notNull().default(false),
    // Set when the user manually moves the status BACKWARDS: automatic status
    // changes then leave this lead alone until they move it forward themselves.
    statusPinned: boolean("status_pinned").notNull().default(false),
    capturedAt: timestamp("captured_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    // The Gmail message this lead came from, for audit / error tracing.
    sourceMessageId: text("source_message_id"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    // Anti-flooding: a job seen again across emails/re-fetches is ignored via
    // ON CONFLICT DO NOTHING against this key (FR-1.5).
    uniqueIndex("job_leads_user_linkedin_job_id_uq").on(
      t.userId,
      t.linkedinJobId,
    ),
    index("job_leads_user_status_idx").on(t.userId, t.status),
    index("job_leads_user_captured_idx").on(t.userId, t.capturedAt.desc()),
    index("job_leads_tags_gin_idx").using("gin", t.tags),
  ],
);

/** Full JD text, AI summary, and notes — 1:1 with a lead (maps JobLeadDetail). */
export const jobLeadDetails = pgTable("job_lead_details", {
  leadId: uuid("lead_id")
    .primaryKey()
    .references(() => jobLeads.id, { onDelete: "cascade" }),
  // Direct owner scoping (in addition to lead_id → job_leads) so every write
  // carries user_id and reads can filter by it (multi-user).
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  jdText: text("jd_text"),
  aiSummary: text("ai_summary"),
  notes: text("notes"),
  // AI salary-expectation estimate for this job (premium) + when it was made.
  salaryInsight: jsonb("salary_insight").$type<SalaryInsight>(),
  salaryInsightAt: timestamp("salary_insight_at", { withTimezone: true }),
});

/** Recruiter / referral contacts tied to a lead (maps Contact). */
export const contacts = pgTable(
  "contacts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    leadId: uuid("lead_id")
      .notNull()
      .references(() => jobLeads.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    title: text("title").notNull().default(""),
    linkedinUrl: text("linkedin_url"),
    connectionType: connectionType("connection_type").notNull(),
    aiParsed: boolean("ai_parsed").notNull().default(false),
    // Orders "contact added" events in the per-lead timeline (FR-6.2).
    addedAt: timestamp("added_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    index("contacts_lead_idx").on(t.leadId),
    // Groups a person across leads for per-contact history (FR-6.1).
    index("contacts_user_linkedin_url_idx").on(t.userId, t.linkedinUrl),
  ],
);

/** AI draft + final sent message per contact (maps OutreachMessage). Stores
 *  both bodies for record-keeping (FR-4.4). */
export const outreachMessages = pgTable(
  "outreach_messages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    leadId: uuid("lead_id")
      .notNull()
      .references(() => jobLeads.id, { onDelete: "cascade" }),
    contactId: uuid("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    kind: outreachKind("kind").notNull(),
    channel: text("channel").notNull(),
    status: outreachStatus("status").notNull().default("draft"),
    draftBody: text("draft_body").notNull(),
    sentBody: text("sent_body"),
    resumeId: uuid("resume_id").references(() => resumes.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    sentAt: timestamp("sent_at", { withTimezone: true }),
  },
  (t) => [
    index("outreach_lead_idx").on(t.leadId),
    index("outreach_contact_idx").on(t.contactId),
  ],
);

/** Follow-up schedule + outcome per outreach message (maps Reminder). */
export const reminders = pgTable(
  "reminders",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    leadId: uuid("lead_id")
      .notNull()
      .references(() => jobLeads.id, { onDelete: "cascade" }),
    // Null for a manual reminder not tied to a specific sent message.
    outreachMessageId: uuid("outreach_message_id").references(
      () => outreachMessages.id,
      { onDelete: "set null" },
    ),
    sequence: integer("sequence").notNull(),
    // Full timestamp (date + time) so reminders can be scheduled for a time of
    // day, not just a day.
    dueDate: timestamp("due_date", { withTimezone: true, mode: "string" }).notNull(),
    outcome: reminderOutcome("outcome").notNull().default("pending"),
    manual: boolean("manual").notNull().default(false),
    label: text("label"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    // Drives the daily due-check cron (TRD §9).
    index("reminders_user_outcome_due_idx").on(t.userId, t.outcome, t.dueDate),
    index("reminders_lead_idx").on(t.leadId),
  ],
);

/** The actionable To-do item; always tied to a job, optionally to a reminder
 *  (maps Task). UI-revealed addition — see the schema plan's Deviations. */
export const tasks = pgTable(
  "tasks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    jobId: uuid("job_id")
      .notNull()
      .references(() => jobLeads.id, { onDelete: "cascade" }),
    reminderId: uuid("reminder_id").references(() => reminders.id, {
      onDelete: "set null",
    }),
    title: text("title").notNull(),
    kind: taskKind("kind").notNull(),
    dueDate: date("due_date", { mode: "string" }),
    status: taskStatus("status").notNull().default("open"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    completedAt: timestamp("completed_at", { withTimezone: true }),
  },
  (t) => [
    index("tasks_user_status_due_idx").on(t.userId, t.status, t.dueDate),
    index("tasks_job_idx").on(t.jobId),
  ],
);

/** Uploaded resume files to draft against / score fit with (maps Resume). */
export const resumes = pgTable(
  "resumes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    label: text("label").notNull(),
    fileName: text("file_name").notNull(),
    fileType: resumeFileType("file_type").notNull(),
    sizeKb: integer("size_kb").notNull(),
    // Phase 3: file lives in blob storage (Vercel Blob/S3/R2) — the Vercel FS
    // is read-only, so we store a URL, not bytes.
    blobUrl: text("blob_url").notNull(),
    // Pasted plain-text of the resume, used by AI fit-scoring (null until the
    // user adds it in Settings).
    resumeText: text("resume_text"),
    isDefault: boolean("is_default").notNull().default(false),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    // At most one default resume per user.
    uniqueIndex("resumes_one_default_per_user_uq")
      .on(t.userId)
      .where(sql`${t.isDefault}`),
  ],
);

/** One settings row per user — backs Settings → Follow-ups + AI provider. */
export const userSettings = pgTable("user_settings", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  reminderIntervalDays: integer("reminder_interval_days").notNull().default(3), // FR-5.1
  staleLeadDays: integer("stale_lead_days").notNull().default(14), // FR-2.4
  // Move a lead's status forward automatically from what the user does on it.
  autoStatus: boolean("auto_status").notNull().default(true),
  // Settings → Notifications "Promotional messages" off, or an unsubscribe link.
  promoOptOut: boolean("promo_opt_out").notNull().default(false),
  promoOptOutAt: timestamp("promo_opt_out_at", { withTimezone: true }),
  // How many follow-ups are scheduled automatically after the first (FR-5.4).
  maxFollowUps: integer("max_follow_ups").notNull().default(2),
  // Automatic lead rules (lib/lead-rules-model.ts); empty = all at their defaults.
  leadRules: jsonb("lead_rules").notNull().default(sql`'{}'::jsonb`),
  // How often the Gmail sync should run for this user (hours): 24/12/6/3/1.
  syncIntervalHours: integer("sync_interval_hours").notNull().default(24),
  defaultResumeId: uuid("default_resume_id").references(() => resumes.id, {
    onDelete: "set null",
  }),
  aiProvider: aiProvider("ai_provider").notNull().default("openai"),
  aiModel: text("ai_model"),
  // Encrypted at rest (TRD §8). Stored as base64(ciphertext); only the last 4
  // chars are ever returned to the client.
  aiKeyCiphertext: text("ai_key_ciphertext"),
  aiKeyLast4: text("ai_key_last4"),
  // User-customized AI instruction prompts (null = use the built-in default).
  promptSummary: text("prompt_summary"),
  promptDraft: text("prompt_draft"),
  promptScore: text("prompt_score"),
  // Onboarding tour version this user finished or skipped (null = never seen).
  // Bump TOUR_VERSION (lib/tour.ts) to show a new tour once to everyone.
  tourVersion: integer("tour_version"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/**
 * The uploaded résumé file bytes, kept out of the resumes table so they're
 * never pulled into a workspace read. One file per résumé (stored in Postgres
 * for now; swap to blob storage at go-live). Text is extracted at upload and
 * lives in resumes.resume_text.
 */
export const resumeFiles = pgTable("resume_files", {
  resumeId: uuid("resume_id")
    .primaryKey()
    .references(() => resumes.id, { onDelete: "cascade" }),
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  contentType: text("content_type").notNull(),
  data: bytea("data").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * Cached AI fit score for a (lead, resume) pair. Computed on demand (never
 * automatically), so the UI shows "NC" until the user triggers a score/rescore.
 * One row per (user, lead, resume); a rescore overwrites it.
 */
/** Every status change the system made on its own, and why (shown on the card). */
export const leadAutoActions = pgTable(
  "lead_auto_actions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    leadId: uuid("lead_id")
      .notNull()
      .references(() => jobLeads.id, { onDelete: "cascade" }),
    rule: text("rule").notNull(),
    fromStatus: leadStatus("from_status").notNull(),
    fromCloseOutcome: closeOutcome("from_close_outcome"),
    toStatus: leadStatus("to_status").notNull(),
    reason: text("reason").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    // The user undid it; that rule leaves this lead alone from then on.
    undoneAt: timestamp("undone_at", { withTimezone: true }),
    // The user changed the status themselves, so the message no longer applies.
    clearedAt: timestamp("cleared_at", { withTimezone: true }),
  },
  (t) => [
    index("lead_auto_actions_user_idx").on(t.userId),
    index("lead_auto_actions_lead_idx").on(t.leadId),
  ],
);

export const fitScores = pgTable(
  "fit_scores",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    leadId: uuid("lead_id")
      .notNull()
      .references(() => jobLeads.id, { onDelete: "cascade" }),
    resumeId: uuid("resume_id")
      .notNull()
      .references(() => resumes.id, { onDelete: "cascade" }),
    score: integer("score").notNull(),
    rationale: text("rationale"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    uniqueIndex("fit_scores_user_lead_resume_uq").on(
      t.userId,
      t.leadId,
      t.resumeId,
    ),
  ],
);

/**
 * App-level SMTP settings for outbound system email (password resets). A single
 * row (id = "app"); a future admin dashboard edits it. The password is
 * encrypted at rest (lib/crypto), like the AI key.
 */
export const smtpConfig = pgTable("smtp_config", {
  id: text("id").primaryKey().default("app"),
  host: text("host").notNull(),
  port: integer("port").notNull().default(587),
  // Legacy boolean kept for the current mailer; `encryption` is the richer choice
  // the admin UI writes (none/starttls/ssl/tls). Mailer reads encryption when set.
  secure: boolean("secure").notNull().default(false),
  encryption: text("encryption").notNull().default("starttls"),
  username: text("username"),
  passwordCiphertext: text("password_ciphertext"),
  fromEmail: text("from_email").notNull(),
  fromName: text("from_name"),
  replyTo: text("reply_to"),
  enabled: boolean("enabled").notNull().default(false),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/* ------------------------------------------------------------------ */
/* Admin: Plans & Pricing + app-level config (single "app" row each)    */
/* ------------------------------------------------------------------ */

/** Subscription plans shown on the admin Plans & Pricing screen. */
export const plans = pgTable("plans", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull(),
  code: text("code").notNull().unique(),
  // Rich-text HTML from the admin editor (sanitize on write when wired).
  description: text("description").notNull().default(""),
  accent: text("accent").notNull().default("indigo"),
  isFree: boolean("is_free").notNull().default(false),
  // Free plan only — days of access before renewal (0 = never expires).
  freeDurationDays: integer("free_duration_days").notNull().default(0),
  // The single plan new sign-ups land on (free plans only; exactly one, enforced
  // by the partial unique index below). Registration is blocked with no default.
  isDefault: boolean("is_default").notNull().default(false),
  // 0 disables that interval.
  monthlyPrice: integer("monthly_price").notNull().default(0),
  yearlyPrice: integer("yearly_price").notNull().default(0),
  currency: text("currency").notNull().default("INR"),
  // null = unlimited.
  limitResumes: integer("limit_resumes"),
  allowCustomPrompts: boolean("allow_custom_prompts").notNull().default(false),
  // Premium feature switches.
  allowNotes: boolean("allow_notes").notNull().default(false),
  allowSalaryInsight: boolean("allow_salary_insight").notNull().default(false),
  // Résumé ATS score checker (Settings → Resumes). Off by default on every plan.
  allowAtsCheck: boolean("allow_ats_check").notNull().default(false),
  // AI mock interviews included each plan period, no carry-over (spec D5). On a
  // Free plan it is once ever, like the Free plan itself.
  aiInterviewsIncluded: integer("ai_interviews_included").notNull().default(0),
  // Open (not archived) leads a user may hold; null = unlimited. Enforced on
  // manual add and alert intake (lib/entitlements.ts).
  limitActiveLeads: integer("limit_active_leads"),
  // "Add with AI" extractions per calendar month; null = unlimited.
  limitAiAddMonthly: integer("limit_ai_add_monthly"),
  // AI outreach / application drafts.
  allowAiDrafts: boolean("allow_ai_drafts").notNull().default(false),
  // AI reads forwarded alerts from supported sites that have no built-in reader.
  allowAiEmailReading: boolean("allow_ai_email_reading").notNull().default(false),
  // Tickets from users on this plan are flagged Priority in the admin inbox.
  prioritySupport: boolean("priority_support").notNull().default(false),
  features: text("features").array().notNull().default(sql`'{}'::text[]`),
  popular: boolean("popular").notNull().default(false),
  // Listed on the public /pricing page (active plans only). Keeps test plans private.
  showOnPricing: boolean("show_on_pricing").notNull().default(false),
  status: planStatus("status").notNull().default("active"),
  // Running count of users who have ever been on this plan — gates deletion.
  everSubscribed: integer("ever_subscribed").notNull().default(0),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
}, (t) => [
  // At most one default sign-up plan across all plans.
  uniqueIndex("plans_one_default_uq").on(t.isDefault).where(sql`${t.isDefault}`),
]);

/** Branding assets (logo, favicon) the admin can change anytime. One row per
 *  kind; bytes stored in-DB (small, few) and served via /api/branding/[kind].
 *  When a kind has no row, the app falls back to its built-in default. */
export const appAssets = pgTable("app_assets", {
  kind: text("kind").primaryKey(), // "logo" | "favicon"
  contentType: text("content_type").notNull(),
  data: bytea("data").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** Settings → General (one "app" row). */
export const appSettings = pgTable("app_settings", {
  id: text("id").primaryKey().default("app"),
  appName: text("app_name").notNull().default("Jobtiva"),
  // Optional short tagline shown under the app name on brand surfaces; gated by showTagline.
  tagline: text("tagline"),
  showTagline: boolean("show_tagline").notNull().default(false),
  supportEmail: text("support_email"),
  allowSignup: boolean("allow_signup").notNull().default(false),
  maintenance: boolean("maintenance").notNull().default(false),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** Settings → Security (one "app" row). Password policy + session length. */
export const securityConfig = pgTable("security_config", {
  id: text("id").primaryKey().default("app"),
  pwMinLength: integer("pw_min_length").notNull().default(8),
  pwRequireUpper: boolean("pw_require_upper").notNull().default(true),
  pwRequireLower: boolean("pw_require_lower").notNull().default(true),
  pwRequireNumber: boolean("pw_require_number").notNull().default(true),
  pwRequireSpecial: boolean("pw_require_special").notNull().default(true),
  sessionValue: integer("session_value").notNull().default(7),
  sessionUnit: text("session_unit").notNull().default("days"),
  // Google reCAPTCHA v3 on the sign-in / password pages (lib/captcha.ts). The
  // secret is encrypted at rest; only its last 4 characters are ever read back.
  captchaEnabled: boolean("captcha_enabled").notNull().default(false),
  captchaSiteKey: text("captcha_site_key"),
  captchaSecretCiphertext: text("captcha_secret_ciphertext"),
  captchaSecretLast4: text("captcha_secret_last4"),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** Settings → Cron & schedule (one "app" row). */
export const cronConfig = pgTable("cron_config", {
  id: text("id").primaryKey().default("app"),
  quietEnabled: boolean("quiet_enabled").notNull().default(false),
  quietFrom: text("quiet_from").notNull().default("22:00"),
  quietTo: text("quiet_to").notNull().default("07:00"),
  quietTz: text("quiet_tz").notNull().default("Asia/Kolkata"),
  quietDays: text("quiet_days").array().notNull().default(sql`'{}'::text[]`),
  purgeEnabled: boolean("purge_enabled").notNull().default(false),
  purgeDays: integer("purge_days").notNull().default(90),
  purgeStatuses: text("purge_statuses").array().notNull().default(sql`'{}'::text[]`),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** Audit log of automatic stale-lead purges, per user per run. Records the policy
 *  in force (days + statuses) and how many leads were deleted per status, so each
 *  deletion is accountable and the user can be notified. */
export const leadPurgeLog = pgTable(
  "lead_purge_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    runAt: timestamp("run_at", { withTimezone: true }).notNull().defaultNow(),
    policyDays: integer("policy_days").notNull(),
    statuses: text("statuses").array().notNull().default(sql`'{}'::text[]`),
    // { [status]: count } of leads deleted in this run.
    counts: jsonb("counts").$type<Record<string, number>>().notNull(),
    totalDeleted: integer("total_deleted").notNull(),
    notified: boolean("notified").notNull().default(false),
  },
  (t) => [index("lead_purge_log_user_idx").on(t.userId, t.runAt.desc())],
);

/** Persistent user notifications shown on the dashboard bell (in addition to the
 *  derived reminder/new-lead items). Created by system events like the lead
 *  purge; mirrors the email the user also receives. */
export const notifications = pgTable(
  "notifications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    type: text("type").notNull(), // e.g. "lead-purge", "system"
    title: text("title").notNull(),
    body: text("body").notNull(),
    href: text("href"), // optional click-through target
    // Set on a broadcast's in-app copy; its full HTML lives on the broadcast.
    broadcastId: uuid("broadcast_id").references(() => broadcasts.id, { onDelete: "cascade" }),
    readAt: timestamp("read_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("notifications_user_idx").on(t.userId, t.createdAt.desc()),
    index("notifications_broadcast_idx").on(t.broadcastId),
  ],
);

/* ---------------- broadcasts ---------------- */

export const broadcastCategory = pgEnum("broadcast_category", ["important", "promotional"]);
export const broadcastChannel = pgEnum("broadcast_channel", ["in_app", "email", "both"]);
export const broadcastStatus = pgEnum("broadcast_status", ["draft", "scheduled", "sending", "sent", "canceled"]);
export const broadcastRecipientStatus = pgEnum("broadcast_recipient_status", ["pending", "sent", "failed", "skipped"]);

/** A message an admin sends to every user (lib/broadcasts-model.ts has the rules). */
export const broadcasts = pgTable(
  "broadcasts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    title: text("title").notNull(),
    contentHtml: text("content_html").notNull().default(""),
    category: broadcastCategory("category").notNull(),
    channel: broadcastChannel("channel").notNull(),
    status: broadcastStatus("status").notNull().default("draft"),
    // Due time for a scheduled send; "Send now" schedules for the moment it's sent.
    scheduledFor: timestamp("scheduled_for", { withTimezone: true }),
    createdBy: text("created_by").references(() => user.id, { onDelete: "set null" }),
    // Who it reached, fixed when sending starts, and the email tallies so far.
    // Kept here so the numbers outlive trimmed notifications and recipient rows.
    inAppCount: integer("in_app_count").notNull().default(0),
    emailTotal: integer("email_total").notNull().default(0),
    emailSent: integer("email_sent").notNull().default(0),
    emailFailed: integer("email_failed").notNull().default(0),
    startedAt: timestamp("started_at", { withTimezone: true }),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
    canceledAt: timestamp("canceled_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [index("broadcasts_due_idx").on(t.status, t.scheduledFor)],
);

/** The email queue for a broadcast: one row per user it's going to. */
export const broadcastRecipients = pgTable(
  "broadcast_recipients",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    broadcastId: uuid("broadcast_id")
      .notNull()
      .references(() => broadcasts.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // The address at send time, so a later email change doesn't redirect it.
    email: text("email").notNull(),
    status: broadcastRecipientStatus("status").notNull().default("pending"),
    attempts: integer("attempts").notNull().default(0),
    lastError: text("last_error"),
    // Set while a worker is sending it, and after a failure (the retry waits
    // until it's old). A crashed worker's claim frees itself the same way.
    lockedAt: timestamp("locked_at", { withTimezone: true }),
    sentAt: timestamp("sent_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("broadcast_recipients_uq").on(t.broadcastId, t.userId),
    index("broadcast_recipients_queue_idx").on(t.status, t.broadcastId),
  ],
);

/** Support tickets — messages users send from the app (e.g. the deactivated-account
 *  "write to admin" flow). Collected for the admin Tickets inbox. User name/email are
 *  snapshotted so a ticket survives user deletion. */
export const supportTickets = pgTable(
  "support_tickets",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Human-readable, sequential reference (shown to users/admins as e.g. TKT-0042).
    // The uuid id stays the internal/system key. Existing rows backfill via the sequence.
    number: integer("number").notNull().generatedByDefaultAsIdentity(),
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    name: text("name").notNull().default(""),
    email: text("email").notNull().default(""),
    subject: text("subject").notNull(),
    // Plain text or admin-safe HTML (the user's own message).
    message: text("message").notNull(),
    // Triage bucket: question | bug | billing | account | other.
    category: text("category").notNull().default("other"),
    // Where it came from: "reactivation", "contact", or a page path.
    source: text("source").notNull().default("contact"),
    status: ticketStatus("status").notNull().default("open"),
    // Account-deletion requests only: set when the user cancels the request.
    // The admin delete re-checks it, so a cancelled request is never acted on.
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    // Read/delivery receipts (chat ticks + unread counts). "last_*_at >= a message's
    // created_at" means that party has delivered/read that message.
    lastReadByUserAt: timestamp("last_read_by_user_at", { withTimezone: true }),
    lastReadByAdminAt: timestamp("last_read_by_admin_at", { withTimezone: true }),
    lastDeliveredToUserAt: timestamp("last_delivered_to_user_at", { withTimezone: true }),
    lastDeliveredToAdminAt: timestamp("last_delivered_to_admin_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [index("support_tickets_status_idx").on(t.status, t.createdAt.desc())],
);

/** Replies on a ticket — two-way: "admin" (support) or "user". Shown in the admin
 *  inbox and the user's in-app conversation view. */
export const ticketReplies = pgTable(
  "ticket_replies",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    ticketId: uuid("ticket_id")
      .notNull()
      .references(() => supportTickets.id, { onDelete: "cascade" }),
    // Who wrote it: "admin" (support) or "user". Existing rows backfill to admin.
    author: text("author").notNull().default("admin"),
    body: text("body").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("ticket_replies_ticket_idx").on(t.ticketId, t.createdAt)],
);

/** Settings → Billing (one "app" row): tax and invoicing. The gateway fields
 *  (enabled, provider, mode, key_id, key_secret_ciphertext) moved to
 *  payment_gateways in 0054 and are no longer read; they stay one release so
 *  an automatic rollback to the previous build still works, then get dropped. */
export const billingConfig = pgTable("billing_config", {
  id: text("id").primaryKey().default("app"),
  // The gateway itself (on/off, mode, keys) is in payment_gateways since 0054;
  // its old columns here were dropped in 0063.
  currency: text("currency").notNull().default("INR"),
  // "GST registered": null = not chosen yet (online payment stays off until
  // Billing is complete), false = not registered (no GST; PAN on a commercial
  // invoice), true = registered (GSTIN, rate, SAC; tax invoice).
  gstRegistered: boolean("gst_registered"),
  pan: text("pan"),
  gstin: text("gstin"),
  sacCode: text("sac_code"),
  taxRate: integer("tax_rate").notNull().default(18),
  pricesIncludeTax: boolean("prices_include_tax").notNull().default(false),
  companyName: text("company_name"),
  companyAddress: text("company_address"),
  invoicePrefix: text("invoice_prefix").notNull().default("JOB-"),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/* ------------------------------------------------------------------ */
/* Payments: gateways, plan orders, renewal reminders                   */
/* Spec: memory payments-plan. Amounts are in paise (smallest unit).    */
/* ------------------------------------------------------------------ */

export const gatewayMode = pgEnum("gateway_mode", ["test", "live"]);
export const billingPeriod = pgEnum("billing_period", ["monthly", "yearly"]);
// ai_interview: a paid AI mock interview (spec D5); no plan, no period.
export const orderKind = pgEnum("order_kind", ["new", "renew", "upgrade", "ai_interview"]);
export const orderStatus = pgEnum("order_status", ["created", "paid", "failed", "cancelled"]);

/** Admin → Settings → Payments: one row per gateway (id = "razorpay", …).
 *  Secrets are encrypted at rest and never leave the server. */
export const paymentGateways = pgTable("payment_gateways", {
  id: text("id").primaryKey(),
  enabled: boolean("enabled").notNull().default(false),
  mode: gatewayMode("mode").notNull().default("test"),
  keyId: text("key_id"),
  keySecretCiphertext: text("key_secret_ciphertext"),
  webhookSecretCiphertext: text("webhook_secret_ciphertext"),
  // Last "Test connection" result.
  lastTestOk: boolean("last_test_ok"),
  lastTestAt: timestamp("last_test_at", { withTimezone: true }),
  // Order when several gateways are offered at checkout.
  sortOrder: integer("sort_order").notNull().default(0),
  updatedBy: text("updated_by").references(() => user.id, { onDelete: "set null" }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** One plan purchase attempt. A financial record: it outlives the user and the
 *  plan (both set null on delete, with name/email/plan snapshots), and is never
 *  purged by data retention. */
export const paymentOrders = pgTable(
  "payment_orders",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Receipt number = receipt_prefix + number zero-padded (e.g. JOB-001201).
    // The prefix is copied from Billing at creation, so receipts never change.
    number: integer("number").notNull().generatedByDefaultAsIdentity(),
    receiptPrefix: text("receipt_prefix").notNull(),
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    userName: text("user_name").notNull().default(""),
    userEmail: text("user_email").notNull().default(""),
    planId: uuid("plan_id").references(() => plans.id, { onDelete: "set null" }),
    planName: text("plan_name").notNull(),
    // Plan orders only; null for an AI interview (kind ai_interview).
    period: billingPeriod("period"),
    kind: orderKind("kind").notNull(),
    status: orderStatus("status").notNull().default("created"),
    currency: text("currency").notNull().default("INR"),
    // Paise: price before GST, GST, and what is charged.
    baseAmount: integer("base_amount").notNull(),
    taxAmount: integer("tax_amount").notNull(),
    totalAmount: integer("total_amount").notNull(),
    taxRate: integer("tax_rate").notNull(),
    pricesIncludeTax: boolean("prices_include_tax").notNull(),
    // Unused value of the previous plan, as extra days (upgrades).
    creditDays: integer("credit_days").notNull().default(0),
    // The term granted; set when the payment is confirmed.
    termStartsAt: timestamp("term_starts_at", { withTimezone: true }),
    termEndsAt: timestamp("term_ends_at", { withTimezone: true }),
    gateway: text("gateway").notNull(),
    mode: gatewayMode("mode").notNull(),
    gatewayOrderId: text("gateway_order_id"),
    gatewayPaymentId: text("gateway_payment_id"),
    // kind ai_interview: the booking this pays for (made first as pending_payment).
    aiInterviewId: uuid("ai_interview_id").references(() => aiInterviews.id, { onDelete: "set null" }),
    // How the user paid, from the gateway (upi, card, netbanking, wallet…).
    method: text("method"),
    // Seller + tax details at payment time (lib/billing-model BillingSnapshot),
    // so later Billing changes never alter a payment or its invoice.
    billingSnapshot: jsonb("billing_snapshot"),
    failureReason: text("failure_reason"),
    paidAt: timestamp("paid_at", { withTimezone: true }),
    failedAt: timestamp("failed_at", { withTimezone: true }),
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    uniqueIndex("payment_orders_number_uq").on(t.number),
    // A gateway order / payment maps to exactly one of our orders (idempotent
    // verify + webhook).
    uniqueIndex("payment_orders_gateway_order_uq").on(t.gateway, t.gatewayOrderId),
    uniqueIndex("payment_orders_gateway_payment_uq").on(t.gateway, t.gatewayPaymentId),
    index("payment_orders_created_idx").on(t.createdAt.desc()),
    index("payment_orders_user_created_idx").on(t.userId, t.createdAt.desc()),
    index("payment_orders_status_created_idx").on(t.status, t.createdAt.desc()),
    // Money sanity, enforced by the database whatever the code does.
    check("payment_orders_amounts_ck", sql`${t.baseAmount} >= 0 and ${t.taxAmount} >= 0 and ${t.totalAmount} = ${t.baseAmount} + ${t.taxAmount}`),
    // Razorpay's minimum charge is 100 paise (₹1.00).
    check("payment_orders_min_total_ck", sql`${t.totalAmount} >= 100`),
    check("payment_orders_credit_days_ck", sql`${t.creditDays} >= 0`),
    // A plan order has a period; an AI interview order has none and no plan.
    check(
      "payment_orders_kind_period_ck",
      sql`(${t.kind}::text = 'ai_interview' and ${t.period} is null) or (${t.kind}::text <> 'ai_interview' and ${t.period} is not null)`,
    ),
    // One paid order per AI interview (a failed try can be retried).
    uniqueIndex("payment_orders_ai_interview_paid_uq").on(t.aiInterviewId).where(sql`${t.status} = 'paid'`),
  ],
);

/** Renewal reminders sent: one row per user, plan expiry and day (7 … 1 days
 *  before). The primary key makes the daily job safe to run twice. */
export const planRemindersSent = pgTable(
  "plan_reminders_sent",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // The expiry the reminder was about (a renewal moves it, starting fresh).
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    daysBefore: integer("days_before").notNull(),
    planId: uuid("plan_id").references(() => plans.id, { onDelete: "set null" }),
    // Plan offered as the upsell in this email, if any.
    upsellPlanId: uuid("upsell_plan_id").references(() => plans.id, { onDelete: "set null" }),
    sentAt: timestamp("sent_at", { withTimezone: true }).notNull().defaultNow(),
    // "sent" or "failed" (with the error), so the job can show and retry failures.
    status: text("status").notNull().default("sent"),
    error: text("error"),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.expiresAt, t.daysBefore] }),
    index("plan_reminders_sent_at_idx").on(t.sentAt.desc()),
    check("plan_reminders_days_ck", sql`${t.daysBefore} between 1 and 7`),
    check("plan_reminders_status_ck", sql`${t.status} in ('sent', 'failed')`),
  ],
);

/** Settings → AI (one "app" row). Admin tools AI key + default user prompts. */
export const appAiConfig = pgTable("app_ai_config", {
  id: text("id").primaryKey().default("app"),
  adminProvider: aiProvider("admin_provider").notNull().default("openai"),
  adminModel: text("admin_model"),
  adminKeyCiphertext: text("admin_key_ciphertext"),
  adminKeyLast4: text("admin_key_last4"),
  defaultPromptSummary: text("default_prompt_summary"),
  defaultPromptDraft: text("default_prompt_draft"),
  defaultPromptScore: text("default_prompt_score"),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** One row per user — the Gmail ingestion rules (Settings → Which emails to read). */
export const gmailConfig = pgTable("gmail_config", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  senders: text("senders").array().notNull().default(sql`'{}'::text[]`),
  label: text("label"),
  subjectKeywords: text("subject_keywords"),
  lookbackDays: integer("lookback_days").notNull().default(30),
  connected: boolean("connected").notNull().default(false),
  // Set while the user has paused syncing (null = active). Stays connected.
  syncPausedAt: timestamp("sync_paused_at", { withTimezone: true }),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** One personal notepad per user (premium for users; always on for admins). */
export const userNotes = pgTable("user_notes", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  // Sanitized rich-text HTML.
  content: text("content").notNull().default(""),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** One row per user — the incremental Gmail sync cursor (TRD §9). */
export const gmailSyncState = pgTable("gmail_sync_state", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  lastHistoryId: text("last_history_id"),
  lastSyncedAt: timestamp("last_synced_at", { withTimezone: true }),
  lastRunAt: timestamp("last_run_at", { withTimezone: true }),
  lastError: text("last_error"),
});

/** Parse failures land here instead of being silently dropped (FR-1.7). */
export const gmailIngestErrors = pgTable("gmail_ingest_errors", {
  id: uuid("id").primaryKey().defaultRandom(),
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  messageId: text("message_id").notNull(),
  reason: text("reason").notNull(),
  rawExcerpt: text("raw_excerpt"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/** Message-level dedupe so a re-delivered email isn't re-parsed. Belt-and-braces
 *  — the linkedin_job_id unique key already prevents duplicate leads. */
export const gmailProcessedMessages = pgTable(
  "gmail_processed_messages",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    messageId: text("message_id").notNull(),
    processedAt: timestamp("processed_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (t) => [
    uniqueIndex("gmail_processed_messages_pk").on(t.userId, t.messageId),
  ],
);

/* ------------------------------------------------------------------ */
/* Email intake — forwarded job alerts (docs/email-forwarding.md)       */
/* Message-level dedupe reuses gmail_processed_messages (RFC Message-ID, */
/* shared with the Connect Gmail path) and parse issues reuse           */
/* gmail_ingest_errors.                                                 */
/* ------------------------------------------------------------------ */

export const inboundStatus = pgEnum("inbound_status", [
  "accepted",
  "rejected",
  "unsupported",
  "duplicate",
  "gmail_code",
  "queued",
  // Plan ended / account deactivated: accepted but not read (lib/intake-pause).
  "paused",
]);

export const inboundParser = pgEnum("inbound_parser", ["linkedin", "none", "naukri", "timesjobs", "glassdoor", "theladders"]);

/** One private forwarding address per user (`<token>@<receiving domain>`).
 *  Resetting replaces the token, so the old address stops working at once. */
export const inboundAddresses = pgTable(
  "inbound_addresses",
  {
    userId: text("user_id")
      .primaryKey()
      .references(() => user.id, { onDelete: "cascade" }),
    token: text("token").notNull(),
    // The user's own on/off switch (the admin's is email_intake_config). Off =
    // mail to this address is dropped; the address and Gmail progress are kept.
    enabled: boolean("enabled").notNull().default(true),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    // Gmail's forwarding confirmation, shown in Settings until confirmed:
    // today a link (mail-settings.google.com/mail/vf-…), in older/other
    // formats a numeric code. gmail_code_at = when either arrived;
    // gmail_confirm_from = the Gmail account that asked to forward here.
    // gmail_confirm_text = that one Google-signed email as plain text, so the
    // user can read it and click the link themselves; cleared once confirmed.
    gmailCode: text("gmail_code"),
    gmailConfirmUrl: text("gmail_confirm_url"),
    gmailConfirmFrom: text("gmail_confirm_from"),
    gmailConfirmText: text("gmail_confirm_text"),
    gmailCodeAt: timestamp("gmail_code_at", { withTimezone: true }),
    // Set when the user says they verified it in Gmail, or at the first alert.
    confirmedAt: timestamp("confirmed_at", { withTimezone: true }),
    firstReceivedAt: timestamp("first_received_at", { withTimezone: true }),
    lastReceivedAt: timestamp("last_received_at", { withTimezone: true }),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [uniqueIndex("inbound_addresses_token_uq").on(t.token)],
);

/** One row per received email — metadata only, never content. Each environment
 *  logs in its own database. Purged after 30 days. */
export const inboundEmailLog = pgTable(
  "inbound_email_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
    // Null when the recipient address matched no user.
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    // Full sender address — kept only for accepted job-site mail.
    fromAddress: text("from_address"),
    // Always kept; the only sender detail for rejected mail.
    fromDomain: text("from_domain").notNull(),
    // The job site the email is about (e.g. "naukri.com") — for a hand-forward,
    // the original sender's domain, not the user's own.
    site: text("site"),
    signingDomain: text("signing_domain"),
    status: inboundStatus("status").notNull(),
    reason: text("reason").notNull(),
    sizeBytes: integer("size_bytes").notNull().default(0),
    messageId: text("message_id"),
    leadsCreated: integer("leads_created").notNull().default(0),
  },
  (t) => [
    index("inbound_email_log_received_idx").on(t.receivedAt.desc()),
    index("inbound_email_log_user_received_idx").on(t.userId, t.receivedAt.desc()),
  ],
);

/** Settings → Email intake (one "app" row): both intake switches + size cap. */
export const emailIntakeConfig = pgTable("email_intake_config", {
  id: text("id").primaryKey().default("app"),
  forwardingEnabled: boolean("forwarding_enabled").notNull().default(true),
  // "Connect Gmail" (Google OAuth) and everything tied to it.
  gmailOAuthEnabled: boolean("gmail_oauth_enabled").notNull().default(true),
  maxBytes: integer("max_bytes").notNull().default(2 * 1024 * 1024),
  // Most jobs the AI reader may take from one email.
  aiMaxJobs: integer("ai_max_jobs").notNull().default(20),
  gmailToggledAt: timestamp("gmail_toggled_at", { withTimezone: true }),
  gmailToggledBy: text("gmail_toggled_by").references(() => user.id, { onDelete: "set null" }),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** How long each kind of log-like data is kept (admin Settings → Data
 *  retention). Applied by the daily purge cron (lib/retention.ts). One row. */
export const retentionConfig = pgTable("retention_config", {
  id: text("id").primaryKey().default("app"),
  inboundLogDays: integer("inbound_log_days").notNull().default(30),
  ingestIssueDays: integer("ingest_issue_days").notNull().default(30),
  processedLedgerDays: integer("processed_ledger_days").notNull().default(180),
  leadPurgeLogDays: integer("lead_purge_log_days").notNull().default(365),
  notificationDays: integer("notification_days").notNull().default(90),
  autoActionDays: integer("auto_action_days").notNull().default(365),
  kbConversationDays: integer("kb_conversation_days").notNull().default(60),
  broadcastQueueDays: integer("broadcast_queue_days").notNull().default(90),
  sentEmailLogDays: integer("sent_email_log_days").notNull().default(30),
  aiInterviewEventDays: integer("ai_interview_event_days").notNull().default(365),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** One row per email the app hands to a channel (admin Monitoring → Sent
 *  emails). Written by lib/sent-email-log.ts from lib/mailer.ts sendMailWith,
 *  never in the way of the send. No email content: who it went to, which email,
 *  the channel and the result. Kind, channel and status are text so a new
 *  channel or kind needs no migration. Trimmed by Data retention. */
export const sentEmailLog = pgTable(
  "sent_email_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    sentAt: timestamp("sent_at", { withTimezone: true }).notNull().defaultNow(),
    toAddress: text("to_address").notNull(),
    // The account the address belonged to when it was sent; gone with the account.
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    // template | broadcast | test (lib/admin/sent-emails-model.ts)
    kind: text("kind").notNull(),
    templateKey: text("template_key"),
    broadcastId: uuid("broadcast_id").references(() => broadcasts.id, { onDelete: "set null" }),
    // The template's name, the broadcast's title or the test's name, as it was.
    label: text("label").notNull(),
    subject: text("subject").notNull().default(""),
    // As shown, e.g. "Amazon SES" or "SMTP".
    channel: text("channel").notNull(),
    // sent | failed
    status: text("status").notNull(),
    error: text("error"),
    messageId: text("message_id"),
  },
  (t) => [
    index("sent_email_log_sent_idx").on(t.sentAt.desc()),
    index("sent_email_log_user_idx").on(t.userId),
  ],
);

/**
 * The last run of each scheduled job (the cron routes), one row per job, kept
 * up to date by runJob in lib/job-runs.ts. Shown in the dashboard's System block
 * (docs/admin-dashboard/spec.md). The job keys are in lib/job-runs-model.ts.
 */
export const jobRuns = pgTable("job_runs", {
  job: text("job").primaryKey(),
  lastStartedAt: timestamp("last_started_at", { withTimezone: true }).notNull(),
  lastFinishedAt: timestamp("last_finished_at", { withTimezone: true }).notNull(),
  lastOk: boolean("last_ok").notNull(),
  // Why the last run failed, short and with key-shaped text masked. Null after a good run.
  lastError: text("last_error"),
  lastDurationMs: integer("last_duration_ms").notNull(),
  lastOkAt: timestamp("last_ok_at", { withTimezone: true }),
  failuresInARow: integer("failures_in_a_row").notNull().default(0),
});

/**
 * Each admin's own dashboard layout: block order and hidden blocks (Edit
 * dashboard). No row means the default layout, so Reset to default deletes it
 * and the admin keeps getting new blocks in their default place. Block ids are
 * BLOCKS in lib/admin/dashboard-model.ts; unknown ones are dropped on read.
 */
export const adminDashboardLayouts = pgTable("admin_dashboard_layouts", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  blockOrder: jsonb("block_order").$type<string[]>().notNull(),
  hidden: jsonb("hidden").$type<string[]>().notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** Emails waiting for the AI reader (no built-in reader, or it found no jobs,
 *  and the user has an AI key). Holds only what the AI needs — the email
 *  reduced to text with numbered link markers, and those links — and is
 *  deleted as soon as the email is processed (or given up on). */
export const inboundAiQueue = pgTable(
  "inbound_ai_queue",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // The inbound_email_log row to complete when the AI is done.
    logId: uuid("log_id").references(() => inboundEmailLog.id, { onDelete: "set null" }),
    messageId: text("message_id").notNull(),
    // Allowed sender's signing domain (e.g. "naukri.com") — the site the jobs belong to.
    site: text("site").notNull(),
    subject: text("subject").notNull().default(""),
    body: text("body").notNull(),
    links: jsonb("links").$type<string[]>().notNull(),
    attempts: integer("attempts").notNull().default(0),
    lockedAt: timestamp("locked_at", { withTimezone: true }),
    nextAt: timestamp("next_at", { withTimezone: true }).notNull().defaultNow(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("inbound_ai_queue_next_idx").on(t.nextAt)],
);

/** Allowed senders: who may send, which DKIM domain must sign, which reader
 *  turns the email into leads ("none" = accepted but logged as unsupported). */
export const inboundSenders = pgTable(
  "inbound_senders",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Exact address or "*@domain", stored lowercase.
    match: text("match").notNull(),
    signingDomain: text("signing_domain").notNull(),
    parser: inboundParser("parser").notNull().default("none"),
    enabled: boolean("enabled").notNull().default(true),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [uniqueIndex("inbound_senders_match_uq").on(t.match)],
);

/* ------------------------------------------------------------------ */
/* How-to guides (admin-managed content, shown on /guides)             */
/* ------------------------------------------------------------------ */

export const guideStatus = pgEnum("guide_status", ["active", "inactive"]);

/**
 * One How-to guide topic = one menu entry on /guides. Managed in the admin
 * panel (Operations → How-to guides); only `active` topics reach users. The
 * body is sanitized rich-text HTML (WordPress-style editor).
 */
export const guideTopics = pgTable(
  "guide_topics",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // URL id: /guides?topic=<slug>.
    slug: text("slug").notNull(),
    title: text("title").notNull(),
    summary: text("summary").notNull().default(""),
    icon: text("icon").notNull().default("book-open"),
    sortOrder: integer("sort_order").notNull().default(0),
    status: guideStatus("status").notNull().default("inactive"),
    inProgress: boolean("in_progress").notNull().default(false),
    // The guide body: rich-text HTML from the admin editor, sanitized on save
    // (and again on read) by lib/guide-html.ts.
    contentHtml: text("content_html").notNull().default(""),
    updatedBy: text("updated_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    uniqueIndex("guide_topics_slug_uq").on(t.slug),
    index("guide_topics_status_order_idx").on(t.status, t.sortOrder),
  ],
);

/**
 * Career profile — what the user tells us about their career and job
 * preferences (Settings → Career profile). One row per user; the repeatable
 * parts live in the three tables below. Feeds the AI features (résumé ATS check,
 * fit score, drafts) only. Name, email, phone and country stay on `user`.
 * Shape + validation: lib/career-profile-model.ts.
 */
export const careerProfiles = pgTable("career_profiles", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  // Basic info
  currentTitle: text("current_title").notNull().default(""),
  city: text("city").notNull().default(""),
  yearsExperience: integer("years_experience"),
  linkedinUrl: text("linkedin_url").notNull().default(""),
  portfolioUrl: text("portfolio_url").notNull().default(""),
  // Professional summary (Markdown)
  summary: text("summary").notNull().default(""),
  // Skills
  skills: text("skills").array().notNull().default(sql`'{}'::text[]`),
  tools: text("tools").array().notNull().default(sql`'{}'::text[]`),
  // Work eligibility
  languages: text("languages").array().notNull().default(sql`'{}'::text[]`),
  workCountries: text("work_countries").array().notNull().default(sql`'{}'::text[]`),
  needsSponsorship: boolean("needs_sponsorship"),
  sponsorshipCountries: text("sponsorship_countries").array().notNull().default(sql`'{}'::text[]`),
  // Job preferences
  targetRoles: text("target_roles").array().notNull().default(sql`'{}'::text[]`),
  seniority: text("seniority").notNull().default(""),
  workModes: text("work_modes").array().notNull().default(sql`'{}'::text[]`),
  preferredLocations: text("preferred_locations").array().notNull().default(sql`'{}'::text[]`),
  employmentTypes: text("employment_types").array().notNull().default(sql`'{}'::text[]`),
  industries: text("industries").array().notNull().default(sql`'{}'::text[]`),
  openToRelocate: boolean("open_to_relocate"),
  noticePeriod: text("notice_period").notNull().default(""),
  // Pay: amount in whole currency units; null amount = not given.
  currentPayAmount: integer("current_pay_amount"),
  currentPayCurrency: text("current_pay_currency"),
  currentPayPeriod: text("current_pay_period"),
  expectedPayAmount: integer("expected_pay_amount"),
  expectedPayCurrency: text("expected_pay_currency"),
  expectedPayPeriod: text("expected_pay_period"),
  // Optional questions (self-identification; "" = not answered)
  gender: text("gender").notNull().default(""),
  disability: text("disability").notNull().default(""),
  veteran: text("veteran").notNull().default(""),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

export const workExperiences = pgTable(
  "work_experiences",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    sortOrder: integer("sort_order").notNull().default(0),
    title: text("title").notNull(),
    company: text("company").notNull(),
    location: text("location").notNull().default(""),
    employmentType: text("employment_type").notNull().default(""),
    startMonth: integer("start_month"),
    startYear: integer("start_year"),
    endMonth: integer("end_month"),
    endYear: integer("end_year"),
    isCurrent: boolean("is_current").notNull().default(false),
    // Achievements, Markdown bullets.
    description: text("description").notNull().default(""),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("work_experiences_user_order_idx").on(t.userId, t.sortOrder)],
);

export const educations = pgTable(
  "educations",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    sortOrder: integer("sort_order").notNull().default(0),
    degree: text("degree").notNull(),
    field: text("field").notNull().default(""),
    institution: text("institution").notNull(),
    startYear: integer("start_year"),
    endYear: integer("end_year"),
    grade: text("grade").notNull().default(""),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("educations_user_order_idx").on(t.userId, t.sortOrder)],
);

export const certifications = pgTable(
  "certifications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    sortOrder: integer("sort_order").notNull().default(0),
    name: text("name").notNull(),
    issuer: text("issuer").notNull().default(""),
    year: integer("year"),
    url: text("url").notNull().default(""),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("certifications_user_order_idx").on(t.userId, t.sortOrder)],
);

/**
 * Latest ATS check per résumé (Settings → Resumes). Hybrid score: code checks
 * (sections, contact, measurable impact, length) + an AI keyword / role match
 * against the user's career profile. The hashes say what the result was based
 * on — if the résumé text or the relevant profile fields change, it's outdated.
 * Result shape: AtsResult in lib/ats-model.ts.
 */
export const resumeAtsChecks = pgTable("resume_ats_checks", {
  resumeId: uuid("resume_id")
    .primaryKey()
    .references(() => resumes.id, { onDelete: "cascade" }),
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  score: integer("score").notNull(),
  result: jsonb("result").notNull(),
  resumeHash: text("resume_hash").notNull(),
  profileHash: text("profile_hash").notNull(),
  checkedAt: timestamp("checked_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * One-time email codes that confirm a destructive account action (reset leads,
 * request account deletion). One live code per user + purpose; only a hash is
 * stored. Short-lived and attempt-limited — see lib/action-codes.ts.
 */
export const actionCodes = pgTable(
  "action_codes",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    purpose: text("purpose").notNull(),
    codeHash: text("code_hash").notNull(),
    attempts: integer("attempts").notNull().default(0),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("action_codes_user_purpose_uq").on(t.userId, t.purpose)],
);

/** Monthly usage counters for plan-limited features (e.g. "Add with AI" on the
 *  Free plan). One row per user + feature + month ("YYYY-MM", UTC). */
export const featureUsage = pgTable(
  "feature_usage",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    feature: text("feature").notNull(),
    month: text("month").notNull(),
    count: integer("count").notNull().default(0),
  },
  (t) => [uniqueIndex("feature_usage_user_feature_month_uq").on(t.userId, t.feature, t.month)],
);

/* ------------------------------------------------------------------ */
/* Admin knowledge base (admin only, never shown to users)              */
/* ------------------------------------------------------------------ */

export const kbArticleSource = pgEnum("kb_article_source", ["repo", "admin"]);
export const kbArticleStatus = pgEnum("kb_article_status", ["draft", "published"]);
export const kbQuestionStatus = pgEnum("kb_question_status", ["open", "covered", "dismissed"]);

/**
 * One knowledge base article. `repo` articles come from docs/knowledge-base/*.md
 * (lib/kb-files.ts syncs them at server start) and are read-only in the admin;
 * `admin` articles are written in the admin editor. The agent answers from
 * published articles only.
 */
export const kbArticles = pgTable(
  "kb_articles",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Repo: the file path without .md ("runbooks/recaptcha-lockout"); admin: generated.
    slug: text("slug").notNull(),
    source: kbArticleSource("source").notNull(),
    title: text("title").notNull(),
    category: text("category").notNull(),
    summary: text("summary").notNull().default(""),
    keywords: text("keywords").array().notNull().default(sql`'{}'::text[]`),
    status: kbArticleStatus("status").notNull().default("draft"),
    // Sanitized HTML for display; plain text for search and answers.
    contentHtml: text("content_html").notNull().default(""),
    contentText: text("content_text").notNull().default(""),
    // Repo only: the file's hash, so an unchanged file is skipped on sync.
    contentHash: text("content_hash"),
    updatedBy: text("updated_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    uniqueIndex("kb_articles_slug_uq").on(t.slug),
    index("kb_articles_status_idx").on(t.status),
  ],
);

/** Earlier saves of an admin article (repo articles have git history instead). */
export const kbArticleVersions = pgTable(
  "kb_article_versions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => kbArticles.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    contentHtml: text("content_html").notNull(),
    savedBy: text("saved_by").references(() => user.id, { onDelete: "set null" }),
    savedAt: timestamp("saved_at", { withTimezone: true }).notNull(),
  },
  (t) => [index("kb_article_versions_article_idx").on(t.articleId, t.savedAt)],
);

/** A conversation with the agent, per admin. Trimmed by Data retention. */
export const kbConversations = pgTable(
  "kb_conversations",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("kb_conversations_user_idx").on(t.userId, t.updatedAt)],
);

export const kbMessages = pgTable(
  "kb_messages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    conversationId: uuid("conversation_id")
      .notNull()
      .references(() => kbConversations.id, { onDelete: "cascade" }),
    role: text("role").notNull(), // "user" | "assistant"
    text: text("text").notNull(),
    // [{ id, title }] of the articles an answer came from (titles kept as they were).
    sources: jsonb("sources").$type<{ id: string; title: string; kind?: "article" | "guide"; href?: string }[]>(),
    unanswered: boolean("unanswered").notNull().default(false),
    // Assistant replies: how it was answered, for usage. Null on older rows.
    outcome: text("outcome").$type<"answered" | "partial" | "unanswered" | "fallback">(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("kb_messages_conversation_idx").on(t.conversationId, t.createdAt)],
);

/** Questions the agent couldn't answer; the same wording is counted, not repeated. */
export const kbQuestions = pgTable(
  "kb_questions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    question: text("question").notNull(),
    // Lowercased, spaces collapsed: what "the same question" means.
    normalized: text("normalized").notNull(),
    timesAsked: integer("times_asked").notNull().default(1),
    // The agent answered some of it; the rest is what needs writing.
    partial: boolean("partial").notNull().default(false),
    status: kbQuestionStatus("status").notNull().default("open"),
    firstAskedAt: timestamp("first_asked_at", { withTimezone: true }).notNull().defaultNow(),
    lastAskedAt: timestamp("last_asked_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("kb_questions_normalized_uq").on(t.normalized)],
);

/* ---------------- email templates ---------------- */

/**
 * The wording an admin saved for one automatic email. The emails themselves,
 * their placeholders and built-in wording live in lib/email-templates-model.ts;
 * `key` is one of those. `content` null (or no row) means the built-in wording.
 * Kept as JSON because it's always read and written as one piece.
 */
export const emailTemplates = pgTable("email_templates", {
  key: text("key").primaryKey(),
  content: jsonb("content").$type<{
    subject: string;
    heading: string;
    bodyHtml: string;
    buttonLabel: string | null;
    footerNote: string;
  }>(),
  updatedBy: text("updated_by").references(() => user.id, { onDelete: "set null" }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

/** Wording an email had before a save or reset; the newest 5 per email are kept. */
export const emailTemplateVersions = pgTable(
  "email_template_versions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    templateKey: text("template_key").notNull(),
    content: jsonb("content")
      .notNull()
      .$type<{ subject: string; heading: string; bodyHtml: string; buttonLabel: string | null; footerNote: string }>(),
    // The built-in wording, saved when the first edit replaced it.
    isDefault: boolean("is_default").notNull().default(false),
    // Who saved this wording and when it was saved.
    savedBy: text("saved_by").references(() => user.id, { onDelete: "set null" }),
    savedAt: timestamp("saved_at", { withTimezone: true }).notNull(),
    // When it was replaced: the history's order, newest first.
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("email_template_versions_key_idx").on(t.templateKey, t.createdAt)],
);

/* ---------------- email delivery ---------------- */

export const emailProvider = pgEnum("email_provider", ["smtp", "ses"]);

/**
 * Which service sends the app's email, and the Amazon SES details (single
 * "app" row; SMTP keeps its own smtp_config row). Spec: memory amazon-ses.
 * The SES secret is encrypted like the SMTP password and never leaves the server.
 */
export const emailDelivery = pgTable("email_delivery", {
  id: text("id").primaryKey().default("app"),
  provider: emailProvider("provider").notNull().default("smtp"),
  sesRegion: text("ses_region").notNull().default(""),
  sesAccessKeyId: text("ses_access_key_id").notNull().default(""),
  sesSecretCiphertext: text("ses_secret_ciphertext"),
  sesFromName: text("ses_from_name").notNull().default(""),
  sesFromEmail: text("ses_from_email").notNull().default(""),
  sesReplyTo: text("ses_reply_to").notNull().default(""),
  // Last Test connection, and what SES reported about the account then.
  sesLastTestOk: boolean("ses_last_test_ok"),
  sesLastTestAt: timestamp("ses_last_test_at", { withTimezone: true }),
  sesAccount: jsonb("ses_account").$type<{
    productionAccess: boolean;
    sendingEnabled: boolean;
    max24HourSend: number;
    sentLast24Hours: number;
    maxSendRate: number;
  }>(),
  updatedBy: text("updated_by").references(() => user.id, { onDelete: "set null" }),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/* ------------------------------------------------------------------ */
/* Mock interviews (docs/interview-prep/spec.md, Release 1: AI)        */
/* ------------------------------------------------------------------ */

export const aiInterviewStatus = pgEnum("ai_interview_status", [
  "pending_payment",
  "ready",
  "in_progress",
  "interrupted",
  "completed",
  "stopped",
  "failed",
  "expired",
]);

/** Admin → Mock interviews → Module settings (single "app" row, spec §4).
 *  Every booking copies the settings in force onto itself (D36). The module AI
 *  key is encrypted like the other secrets and never leaves the server. */
export const mockInterviewConfig = pgTable(
  "mock_interview_config",
  {
    id: text("id").primaryKey().default("app"),
    // Open / Coming soon for each part (D9 switches).
    aiState: text("ai_state").notNull().default("coming_soon"),
    humanState: text("human_state").notNull().default("coming_soon"),
    applicationsOpen: boolean("applications_open").notNull().default(false),
    pauseBookings: boolean("pause_bookings").notNull().default(false),
    // The module's own AI key (D9), separate from users' keys and the KB key.
    aiProvider: aiProvider("ai_provider").notNull().default("openai"),
    aiModel: text("ai_model"),
    aiKeyCiphertext: text("ai_key_ciphertext"),
    aiKeyLast4: text("ai_key_last4"),
    aiLastTestOk: boolean("ai_last_test_ok"),
    aiLastTestAt: timestamp("ai_last_test_at", { withTimezone: true }),
    categories: text("categories").array().notNull().default(sql`'{}'::text[]`),
    durations: integer("durations").array().notNull().default(sql`'{15,30,45,60}'::integer[]`),
    minutesPerQuestion: real("minutes_per_question").notNull().default(2),
    wrapUpMinutes: integer("wrap_up_minutes").notNull().default(10),
    resumeWindowMinutes: integer("resume_window_minutes").notNull().default(15),
    paceGraceMinutes: integer("pace_grace_minutes").notNull().default(5),
    bookingValidDays: integer("booking_valid_days").notNull().default(30),
    expiryReminderDays: integer("expiry_reminder_days").notNull().default(3),
    // Per difficulty: rate per minute (paise) and its own discount (D5).
    pricing: jsonb("pricing").$type<PricingByDifficulty>().notNull(),
    weights: jsonb("weights").$type<MetricWeights>().notNull(),
    // null = the built-in default prompt.
    promptQuestionPlan: text("prompt_question_plan"),
    promptInterviewer: text("prompt_interviewer"),
    promptEvaluation: text("prompt_evaluation"),
    updatedBy: text("updated_by").references(() => user.id, { onDelete: "set null" }),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    check("mic_states_ck", sql`${t.aiState} in ('open', 'coming_soon') and ${t.humanState} in ('open', 'coming_soon')`),
    check(
      "mic_numbers_ck",
      sql`${t.minutesPerQuestion} between 1 and 5 and ${t.wrapUpMinutes} between 0 and 20 and ${t.resumeWindowMinutes} between 5 and 60
        and ${t.paceGraceMinutes} between 0 and 15 and ${t.bookingValidDays} between 1 and 365
        and ${t.expiryReminderDays} >= 0 and ${t.expiryReminderDays} < ${t.bookingValidDays}`,
    ),
  ],
);

/** One AI mock interview, from booking to the end (spec D13a–e). A booking
 *  has one session: resuming continues it, and a give-back makes a new booking
 *  (credited_from_id). Deleted with the account; kept otherwise (D53). */
export const aiInterviews = pgTable(
  "ai_interviews",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    status: aiInterviewStatus("status").notNull().default("ready"),
    // The candidate's setup.
    role: text("role").notNull(),
    industry: text("industry").notNull(),
    category: text("category").notNull(),
    difficulty: text("difficulty").notNull(),
    durationMin: integer("duration_min").notNull(),
    topics: text("topics").array().notNull().default(sql`'{}'::text[]`),
    // The lead it was booked for, with a copy of its label so the interview
    // still reads right after the lead is deleted.
    leadId: uuid("lead_id").references(() => jobLeads.id, { onDelete: "set null" }),
    leadLabel: text("lead_label"),
    // Resume and job description as the AI will read them, copied at booking.
    // An uploaded file is read and discarded; only its text is kept.
    resumeId: uuid("resume_id").references(() => resumes.id, { onDelete: "set null" }),
    resumeSource: text("resume_source").notNull(), // saved | upload | paste
    resumeLabel: text("resume_label").notNull().default(""),
    resumeText: text("resume_text").notNull().default(""),
    jobDescriptionSource: text("job_description_source").notNull(), // lead | paste | none
    jobDescription: text("job_description").notNull().default(""),
    // How it was covered (D5). Paid: price before and after the level's discount.
    coverage: text("coverage").notNull(),
    planName: text("plan_name"),
    // Plan allowance: the plan expiry it counted against. A renewal or upgrade
    // moves the expiry, so the count starts fresh (no carry-over).
    allowancePeriodEnds: timestamp("allowance_period_ends", { withTimezone: true }),
    priceFullPaise: integer("price_full_paise").notNull().default(0),
    pricePaise: integer("price_paise").notNull().default(0),
    discountPercent: integer("discount_percent").notNull().default(0),
    // Given back by admin: the interview it replaces, who and why (D55).
    creditedFromId: uuid("credited_from_id").references((): AnyPgColumn => aiInterviews.id, { onDelete: "set null" }),
    creditedBy: text("credited_by").references(() => user.id, { onDelete: "set null" }),
    creditNote: text("credit_note"),
    // Booking life (D13b).
    validUntil: timestamp("valid_until", { withTimezone: true }).notNull(),
    expiryReminderSentAt: timestamp("expiry_reminder_sent_at", { withTimezone: true }),
    settings: jsonb("settings").$type<InterviewSettingsSnapshot>().notNull(),
    // The run. The clock counts connected seconds only (D13e).
    questionPlan: jsonb("question_plan").$type<PlannedQuestion[]>(),
    questionsAsked: integer("questions_asked").notNull().default(0),
    activeSeconds: integer("active_seconds").notNull().default(0),
    startedAt: timestamp("started_at", { withTimezone: true }),
    lastActiveAt: timestamp("last_active_at", { withTimezone: true }),
    interruptedAt: timestamp("interrupted_at", { withTimezone: true }),
    wrapUpStartedAt: timestamp("wrap_up_started_at", { withTimezone: true }),
    endedAt: timestamp("ended_at", { withTimezone: true }),
    endReason: text("end_reason"),
    // AI use, for admin usage and cost (D56).
    aiProvider: aiProvider("ai_provider"),
    aiModel: text("ai_model"),
    tokensIn: integer("tokens_in").notNull().default(0),
    tokensOut: integer("tokens_out").notNull().default(0),
    aiCostPaise: real("ai_cost_paise").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    index("ai_interviews_user_created_idx").on(t.userId, t.createdAt.desc()),
    index("ai_interviews_created_idx").on(t.createdAt.desc()),
    index("ai_interviews_status_valid_idx").on(t.status, t.validUntil),
    index("ai_interviews_user_period_idx").on(t.userId, t.allowancePeriodEnds),
    // An interview can be given back once.
    uniqueIndex("ai_interviews_credited_from_uq").on(t.creditedFromId),
    check("ai_interviews_difficulty_ck", sql`${t.difficulty} in ('Easy', 'Medium', 'Hard')`),
    check("ai_interviews_duration_ck", sql`${t.durationMin} between 5 and 60`),
    check("ai_interviews_coverage_ck", sql`${t.coverage} in ('plan', 'free', 'paid', 'credit')`),
    check("ai_interviews_resume_source_ck", sql`${t.resumeSource} in ('saved', 'upload', 'paste')`),
    check("ai_interviews_jd_source_ck", sql`${t.jobDescriptionSource} in ('lead', 'paste', 'none')`),
    check(
      "ai_interviews_money_ck",
      sql`${t.priceFullPaise} >= 0 and ${t.pricePaise} >= 0 and ${t.pricePaise} <= ${t.priceFullPaise} and ${t.discountPercent} between 0 and 100`,
    ),
    // A give-back always says why.
    check("ai_interviews_credit_ck", sql`${t.coverage} <> 'credit' or (${t.creditedFromId} is not null and length(${t.creditNote}) >= 10)`),
  ],
);

/** The conversation, one row per question, follow-up or answer. Kept with the
 *  interview (D53). */
export const aiInterviewMessages = pgTable(
  "ai_interview_messages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    interviewId: uuid("interview_id")
      .notNull()
      .references(() => aiInterviews.id, { onDelete: "cascade" }),
    seq: integer("seq").notNull(),
    sender: text("sender").notNull(), // ai | candidate
    kind: text("kind").notNull(), // question | follow_up | answer | closing
    // The planned question a question opens (shown as "Question n").
    questionNo: smallint("question_no"),
    text: text("text").notNull(),
    // Seconds on the interview clock when sent.
    clockSeconds: integer("clock_seconds").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("ai_interview_messages_seq_uq").on(t.interviewId, t.seq),
    check("ai_interview_messages_sender_ck", sql`${t.sender} in ('ai', 'candidate')`),
    check("ai_interview_messages_kind_ck", sql`${t.kind} in ('question', 'follow_up', 'answer', 'closing')`),
  ],
);

/** What happened during an interview (D13): start, disconnects, resume,
 *  wrap-up, end, errors. Admin reads it before giving an interview back.
 *  Trimmed by Data retention (ai_interview_event_days). */
export const aiInterviewEvents = pgTable(
  "ai_interview_events",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    interviewId: uuid("interview_id")
      .notNull()
      .references(() => aiInterviews.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    detail: text("detail").notNull().default(""),
    clockSeconds: integer("clock_seconds").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("ai_interview_events_interview_idx").on(t.interviewId, t.createdAt),
    index("ai_interview_events_created_idx").on(t.createdAt),
  ],
);

/** One report, in the format shared by AI and human interviews (D49). Release
 *  2 links human bookings here too. The five scores are columns so the
 *  Performance page can query them. */
export const interviewEvaluations = pgTable(
  "interview_evaluations",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    source: text("source").notNull(), // ai | human
    aiInterviewId: uuid("ai_interview_id").references(() => aiInterviews.id, { onDelete: "cascade" }),
    status: text("status").notNull().default("draft"), // draft | submitted
    // Interviewer evaluations only: the name the candidate sees.
    evaluatorName: text("evaluator_name"),
    communication: smallint("communication"),
    technical: smallint("technical"),
    confidence: smallint("confidence"),
    problemSolving: smallint("problem_solving"),
    relevance: smallint("relevance"),
    // The weights used, and the overall score out of 100 they gave.
    weights: jsonb("weights").$type<MetricWeights>(),
    overall: smallint("overall"),
    writing: jsonb("writing").$type<ReportWriting>(),
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    uniqueIndex("interview_evaluations_ai_uq").on(t.aiInterviewId),
    index("interview_evaluations_user_submitted_idx").on(t.userId, t.submittedAt.desc()),
    check("interview_evaluations_source_ck", sql`${t.source} in ('ai', 'human')`),
    check("interview_evaluations_status_ck", sql`${t.status} in ('draft', 'submitted')`),
    check(
      "interview_evaluations_scores_ck",
      sql`coalesce(${t.communication}, 1) between 1 and 10 and coalesce(${t.technical}, 1) between 1 and 10
        and coalesce(${t.confidence}, 1) between 1 and 10 and coalesce(${t.problemSolving}, 1) between 1 and 10
        and coalesce(${t.relevance}, 1) between 1 and 10 and coalesce(${t.overall}, 0) between 0 and 100`,
    ),
    // A submitted report is complete.
    check(
      "interview_evaluations_submitted_ck",
      sql`${t.status} <> 'submitted' or (${t.communication} is not null and ${t.technical} is not null and ${t.confidence} is not null
        and ${t.problemSolving} is not null and ${t.relevance} is not null and ${t.overall} is not null and ${t.writing} is not null
        and ${t.submittedAt} is not null)`,
    ),
  ],
);
